javascript:if (typeof dijit === 'undefined') return true;

const typ = tag('rozpocet.typtabora');
const max = Number(typ === 'denny' ? tag('rozpocet.typtabora.denny.maxd')
                   : typ === 'pobytovy' ? tag('rozpocet.typtabora.pobytovy.maxp') : 0);
if (!max) return true;

const w = dijit.byId('rozpocet.vydavky.requested_sum');
const sum = Number(w && w.get('value')) || 0;

const eur = n => n.toLocaleString('sk-SK', {maximumFractionDigits: 2}) + ' €';
return sum <= max || 'Celková suma žiadaná z BBSK (' + eur(sum) + ') prekračuje maximálnu sumu pre '
  + (typ === 'denny' ? 'denný' : 'pobytový') + ' tábor (' + eur(max) + ') o ' + eur(sum - max)
  + '.';
